INSERT INTO `npc_text_locale` (`ID`,`Locale`,`Text0_0`,`Text1_0`,`Text2_0`,`Text3_0`,`Text4_0`,`Text5_0`,`Text6_0`,`Text7_0`) VALUES
(@STORIES_START+0,'deDE','Als ich jung war, habe ich mich drei Tage lang im Dämmerwald verlaufen.','Jede Nacht heulten die Worgen näher an meinem kleinen Feuer.','In der dritten Nacht setzte sich eine Gestalt im schwarzen Umhang mir gegenüber.','Sie sagte nur: "Folge den Krähen nach Dunkelhain." Dann war sie verschwunden.','Ich folgte den Krähen. Bis heute weiß ich nicht, wer das war.',NULL,NULL,NULL),
(@STORIES_START+1,'deDE','Der Dämmerwald ist mir unheimlich.','Worgen? Ich wäre den ganzen Weg nach Hause gerannt.','Vielleicht ein Geist der Nachtwache?','Brrr...',NULL,NULL,NULL,NULL),
(@STORIES_START+2,'deDE','Hab ich euch mal von dem Murloc erzählt, der meine Stiefel geklaut hat?','Ich angelte bei Westfall, die Stiefel neben mir im Sand.','Ein Gurgeln, ein Platschen, und meine Stiefel marschierten ins Meer.','Eine Woche später sah ich einen Murlochäuptling damit. Beide an einem Fuß.',NULL,NULL,NULL,NULL),
(@STORIES_START+3,'deDE','Mrglglgl!','Hast du sie zurückbekommen?','Beide an einem Fuß? Hah!','Murlocs sind die Schlimmsten.',NULL,NULL,NULL,NULL),
(@STORIES_START+4,'deDE','Mein Großvater kämpfte im Zweiten Krieg am Dunklen Portal.','Er sagte, der Himmel dort war blutrot, bei Tag und bei Nacht.','Als das Portal zerstört wurde, bebte der Boden eine Stunde lang.','Er hat einen Splitter dieses Steins bis zu seinem Tod aufbewahrt.','Jetzt trage ich ihn bei mir. Als Glücksbringer, schätze ich.',NULL,NULL,NULL),
(@STORIES_START+5,'deDE','Ein wahrer Held.','Darf ich den Splitter sehen?','Die Verwüsteten Lande sehen immer noch so aus.','Möge er in Frieden ruhen.',NULL,NULL,NULL,NULL),
(@STORIES_START+6,'deDE','Einmal wollte ich im Brachland einen Raptor zähmen.','Ich hatte Fleisch, ein Seil und jede Menge Selbstvertrauen.','Der Raptor hatte Zähne und sechs Freunde.','Ich verbrachte die Nacht auf einem Kodoskelett und sang, um sie fernzuhalten.',NULL,NULL,NULL,NULL),
(@STORIES_START+7,'deDE','Sechs Freunde! Hahaha!','Hat das Singen geholfen?','Raptoren sind keine Haustiere.','Für das Lied würde ich bezahlen.',NULL,NULL,NULL,NULL),
(@STORIES_START+8,'deDE','Im Schlingendorntal traf ich einen Goblin, der Karten zu verborgenen Schätzen verkaufte.','Zehn Gold pro Karte. Ich kaufte drei.','Alle drei Kreuze zeigten auf seinen eigenen Laden.','Er hatte ein großes Schild: "Schatz im Inneren! Alles muss raus!"',NULL,NULL,NULL,NULL),
(@STORIES_START+9,'deDE','Typisch Goblin.','Dreißig Gold... autsch.','Hah! Schlaues Kerlchen.','Hast du im Laden was gekauft?',NULL,NULL,NULL,NULL),
(@STORIES_START+10,'deDE','Ich habe einmal eine Karawane durch das Ödland begleitet.','Die Hitze war so schlimm, dass unser Wasser warm wie Suppe wurde.','Nachts hörten wir die schwarzen Drachen aus der Schlucht von Lethlor brüllen.','Ein Welpe landete auf unserem Wagen, fraß unseren Käse und flog davon.','Wir meldeten ein fehlendes Käserad, Ursache: Drachenangriff.',NULL,NULL,NULL),
(@STORIES_START+11,'deDE','Ein Käsedieb mit Flügeln!','Das Ödland ist kein Ort für Karawanen.','Wenigstens war es nicht der Ausgewachsene.','Hahaha, Drachenangriff!',NULL,NULL,NULL,NULL),
(@STORIES_START+12,'deDE','Habt ihr je die Nordlichter über Nordend gesehen?','Ich habe einmal auf einem Gletscher in der Boreanischen Tundra gelagert.','Der Himmel wurde grün und blau, als würde die ganze Welt atmen.','Für einen Moment vergaß ich die Geißel, die Kälte, einfach alles.',NULL,NULL,NULL,NULL),
(@STORIES_START+13,'deDE','Das klingt wunderschön.','Ich würde da oben erfrieren.','Eines Tages sehe ich mir das an.','Schönheit und Gefahr, Seite an Seite.',NULL,NULL,NULL,NULL),
(@STORIES_START+14,'deDE','Mein erster Dungeon waren die Todesminen.','Unser Tank rannte rein, bevor irgendwer bereit war.','Unser Heiler rannte in die andere Richtung raus.','Irgendwie haben wir VanCleef trotzdem besiegt. Keine Ahnung, wie.','Ich höre diese Kanone heute noch in meinen Träumen.',NULL,NULL,NULL),
(@STORIES_START+15,'deDE','Klassischer Tank.','Hahaha, der Heiler!','Die Kanone! Daran erinnere ich mich!','Glück der Tapferen.',NULL,NULL,NULL,NULL),
(@STORIES_START+16,'deDE','Es gibt eine alte Trollgeschichte über den Loa des Mondes.','Man sagt, er spricht nur zu denen, die nicht schlafen können.','Er verrät dir ein Geheimnis, und du darfst es niemals weitersagen.','Ich schlafe seit Jahren schlecht. Zieht eure eigenen Schlüsse.',NULL,NULL,NULL,NULL),
(@STORIES_START+17,'deDE','Und was war das Geheimnis?','Ach komm, erzähl schon!','Ich schlafe lieber gut.','Geheimnisvoll...',NULL,NULL,NULL,NULL),
(@STORIES_START+18,'deDE','Einmal bin ich in Eisenschmiede bei einem Trinkwettbewerb gelandet.','Gegen einen Zwerg. Ich weiß, ich weiß.','Nach dem neunten Krug sah ich zwei Große Schmieden.','Ich wachte in der Tiefenbahn auf, halb auf dem Weg nach Sturmwind.','Der Zwerg? Der trank noch, als ich zurückkam.',NULL,NULL,NULL),
(@STORIES_START+19,'deDE','Fordere niemals einen Zwerg heraus.','Neun Krüge? Respekt.','Die Bahn! Hahaha!','Zwerge sind aus Stein, ich schwör\'s.',NULL,NULL,NULL,NULL),
(@STORIES_START+20,'deDE','Bei Tarrens Mühle traf ich einen Bauern, der mit seiner Vogelscheuche redete.','Er sagte, sie warne ihn jedes Mal, wenn die Verlassenen näher kamen.','Ich lachte. Dann drehte die Vogelscheuche ihren Kopf zu mir.','Ich bin vor dem Abendessen gegangen. Sehr höflich. Sehr schnell.',NULL,NULL,NULL,NULL),
(@STORIES_START+21,'deDE','Nein. Nein, nein, nein.','Sie hat den Kopf gedreht?!','Vorgebirge ist voller seltsamer Leute.','Kluge Entscheidung.',NULL,NULL,NULL,NULL),
(@STORIES_START+22,'deDE','Das Angeln habe ich von einem alten Nachtelfen in Auberdine gelernt.','Er sagte: "Die Fische merken, wenn du ungeduldig bist."','Ich saß sechs Stunden da, ohne einen einzigen Biss.','Er fing vierzig. Und hat die ganze Zeit gesummt.','Jetzt summe ich auch. Ich fange immer noch nichts, aber ich bin glücklicher.',NULL,NULL,NULL),
(@STORIES_START+23,'deDE','Geduld ist eine Fähigkeit.','Vierzig? Das ist unfair.','Glück ist mehr wert als Fisch.','Summ uns die Melodie vor!',NULL,NULL,NULL,NULL),
(@STORIES_START+24,'deDE','Im Scharlachroten Kloster sah ich einen Mann zwei Tage lang beten.','Kein Essen, kein Wasser, nur Gebete.','Ich fragte ihn, wofür er betet.','Er sagte: "Dass ich mich in allem irre."','Ich denke oft an ihn.',NULL,NULL,NULL),
(@STORIES_START+25,'deDE','Das ist... traurig.','Der Kreuzzug hat viele gute Männer zerbrochen.','Tiefe Worte.','Vielleicht hat er seine Antwort gefunden.',NULL,NULL,NULL,NULL),
(@STORIES_START+26,'deDE','Ich bin einmal auf einem Greif geflogen, der mich gehasst hat.','Bei jedem Flug machte er einen Looping über Loch Modan.','Der Flugmeister schwor, dass er das bei niemandem sonst tat.','Einmal brachte ich ihm einen Apfel. Er fraß den Apfel und die Tasche.',NULL,NULL,NULL,NULL),
(@STORIES_START+27,'deDE','Greifen haben ihre eigene Meinung.','Ein Looping! Da wäre mein Mittagessen weg.','Und die Tasche! Hahaha!','Vielleicht mochte er dich, auf seine Art.',NULL,NULL,NULL,NULL),
(@STORIES_START+28,'deDE','Im Eschental gibt es eine Quelle, die dir deine Zukunft zeigt.','Ich habe natürlich hineingeschaut.','Ich sah mich selbst, älter, an einem Lagerfeuer wie diesem.','Und erzählte eine Geschichte über eine Quelle im Eschental.',NULL,NULL,NULL,NULL),
(@STORIES_START+29,'deDE','Moment... das ist jetzt?','Da bekomme ich Gänsehaut.','Siehst du jetzt älter aus?','Die Geister haben Humor.',NULL,NULL,NULL,NULL),
(@STORIES_START+30,'deDE','Ein Gnom in Beutebucht hat mir einen "selbstkochenden Topf" verkauft.','Man füllt Wasser rein, drückt den Knopf, und er kocht.','Gekocht hat er, oh ja. Sich selbst, den Tisch und die halbe Taverne.','Der Gnom nannte es einen "erfolgreichen Feldversuch".',NULL,NULL,NULL,NULL),
(@STORIES_START+31,'deDE','Gnomische Ingenieurskunst...','Die halbe Taverne?!','Erfolgreich, zumindest fürs Feuer.','Hahaha, natürlich ist er explodiert.',NULL,NULL,NULL,NULL),
(@STORIES_START+32,'deDE','Als ich Rekrut war, ließ uns der Feldwebel um Goldhain laufen.','Zwanzig Runden, volle Rüstung, jeden Morgen.','Eines Morgens schloss sich ein Kobold an und lief mit.','Er war schneller als die Hälfte von uns. Der Feldwebel wollte ihn rekrutieren.',NULL,NULL,NULL,NULL),
(@STORIES_START+33,'deDE','Du nicht nehmen Kerze!','Ein Koboldrekrut! Hahaha!','Zwanzig Runden in Platte? Autsch.','Ist er der Armee beigetreten?',NULL,NULL,NULL,NULL),
(@STORIES_START+34,'deDE','Schon mal vom Geisterschiff vor der Küste der Dunkelküste gehört?','Seeleute sagen, es erscheint, wenn der Nebel am dichtesten ist.','Keine Lichter, keine Mannschaft, aber man hört jemanden eine Glocke läuten.','Ich hörte die Glocke einmal. Am nächsten Morgen war mein Boot voller Seetang.',NULL,NULL,NULL,NULL),
(@STORIES_START+35,'deDE','So fangen Legenden an.','Ich segle nie wieder nachts.','Vielleicht nur ein verirrter Fischer?','Unheimlich...',NULL,NULL,NULL,NULL),
(@STORIES_START+36,'deDE','Ich habe mal einem Tauren geholfen, seinen verlorenen Kodo zu suchen.','Wir suchten zwei ganze Tage in Mulgore.','Endlich fanden wir ihn in Donnerfels, oben auf dem Aufzug.','Bis heute weiß niemand, wie er da hinaufgekommen ist.',NULL,NULL,NULL,NULL),
(@STORIES_START+37,'deDE','Auf dem Aufzug?!','Kodos sind schlauer, als sie aussehen.','Hah! Die Erdenmutter wirkt auf seltsame Weise.','Ich liebe diese Geschichte.',NULL,NULL,NULL,NULL),
(@STORIES_START+38,'deDE','Die schlimmste Nacht meines Lebens war in Karazhan.','Die Geister dort feiern jede Nacht ein Festmahl.','Sie luden mich ein. Ich war höflich. Ich setzte mich.','Die Suppe war kalt, der Gastgeber tot, und die Musik hörte nie auf.','Ich ging bei Sonnenaufgang. Sie baten mich, nächste Woche wiederzukommen.',NULL,NULL,NULL),
(@STORIES_START+39,'deDE','Bist du wieder hingegangen?','Medivhs Turm ist verflucht.','Kalte Suppe ist der wahre Horror.','Ich wäre schreiend weggerannt.',NULL,NULL,NULL,NULL),
(@STORIES_START+40,'deDE','In Nagrand sah ich im Morgengrauen die schwebenden Inseln.','Wasserfälle stürzten von ihnen ins Nichts.','Ein alter Ork saß neben mir und sagte eine Stunde lang nichts.','Dann sagte er: "Das war unsere Heimat, bevor wir uns selbst vergaßen."',NULL,NULL,NULL,NULL),
(@STORIES_START+41,'deDE','Nagrand ist der letzte schöne Ort der Scherbenwelt.','Der alte Ork kannte Trauer.','Schwere Worte.','Diese Inseln würde ich gern sehen.',NULL,NULL,NULL,NULL),
(@STORIES_START+42,'deDE','Ich habe mal meinen ganzen Geldbeutel auf ein Rennen in Gadgetzan gesetzt.','Zwei Goblins, zwei Raketenwagen, eine gerade Strecke.','Beide Raketen explodierten am Start.','Der Buchmacher sagte, keiner hat gewonnen, also behielt er das ganze Geld.',NULL,NULL,NULL,NULL),
(@STORIES_START+43,'deDE','Goblins gewinnen immer.','Natürlich sind sie explodiert.','Du lernst es nie, oder?','Der Buchmacher war der wahre Rennfahrer.',NULL,NULL,NULL,NULL),
(@STORIES_START+44,'deDE','Meine Mentorin war eine Priesterin, die nie die Stimme erhob.','Einmal umzingelten Banditen unser Lager.','Sie ging hinaus, sah ihren Anführer an und bot ihm Tee an.','Er trank ihn. Sie gingen. Niemand hat je verstanden, warum.',NULL,NULL,NULL,NULL),
(@STORIES_START+45,'deDE','Was war in dem Tee?','Das Licht wirkt auf leise Weise.','Die möchte ich kennenlernen.','Freundlichkeit ist stärker als Stahl.',NULL,NULL,NULL,NULL),
(@STORIES_START+46,'deDE','Ich wurde mal in Alterac von einem Yeti verfolgt.','Ich rannte, er rannte. Ich rutschte einen Hang runter, er auch.','Unten blieb er stehen, sah mich an und lachte.','Ich schwöre, der Yeti hat nur gespielt.',NULL,NULL,NULL,NULL),
(@STORIES_START+47,'deDE','Ein verspielter Yeti! Hahaha!','Ich glaub dir kein Wort.','Habt ihr nochmal gespielt?','Lachende Yetis... was kommt als Nächstes?',NULL,NULL,NULL,NULL),
(@STORIES_START+48,'deDE','Man sagt, Dalaran wurde in einer einzigen Nacht in den Himmel gehoben.','Ein Bauer beim alten Krater hat mir erzählt, dass er zugesehen hat.','"Erst leuchtete die Stadt, dann summte sie, dann ist sie einfach gegangen."','Seitdem wartet er, dass sie zurückkommt. Er schuldet ihnen Geld.',NULL,NULL,NULL,NULL),
(@STORIES_START+49,'deDE','Eine fliegende Stadt. Typisch Magier.','Er schuldet ihnen Geld? Hahaha!','Das Summen würde ich gern hören.','Magier machen nie etwas leise.',NULL,NULL,NULL,NULL),
(@STORIES_START+50,'deDE','Ich habe einen Winter bei den Wintersäblerausbildern in Winterquell verbracht.','Jeden Morgen fütterte ich die Jungen mit gefrorenem Fisch.','Eines folgte mir überall hin, sogar zum Abort.','Als ich ging, saß es am Tor und wartete tagelang.',NULL,NULL,NULL,NULL),
(@STORIES_START+51,'deDE','Das ist so süß.','Sogar zum Abort! Hahaha!','Du solltest es holen gehen.','Armes kleines Ding.',NULL,NULL,NULL,NULL),
(@STORIES_START+52,'deDE','Schon mal an der Wegkreuzung gestanden, während die Zentauren angriffen?','Überall Pfeile, die ganze Palisade bebte.','Und der Gastwirt schenkte einfach weiter Getränke aus.','Er sagte: "Überfälle kommen und gehen. Durst bleibt für immer."',NULL,NULL,NULL,NULL),
(@STORIES_START+53,'deDE','Ein weiser Gastwirt.','Zentauren sind fies.','Darauf trinke ich!','Hah! Durst bleibt für immer.',NULL,NULL,NULL,NULL),
(@STORIES_START+54,'deDE','In Zul\'Drak fand ich eine Trollstatue, die weinte.','Echte Tränen, die am Stein herunterliefen.','Ich wischte ihr Gesicht mit meinem Ärmel ab.','Am nächsten Tag waren die Tränen weg und zu ihren Füßen wuchs eine Blume.',NULL,NULL,NULL,NULL),
(@STORIES_START+55,'deDE','Das ist wunderschön.','Die Götter der Drakkari sterben. Vielleicht war es Trauer.','Eine kleine Freundlichkeit.','Ich hab Gänsehaut.',NULL,NULL,NULL,NULL),
(@STORIES_START+56,'deDE','Ich wollte mich mal aus Spaß nach Unterstadt schleichen.','Ich malte mein Gesicht grau an und ging, als hätte ich Rückenschmerzen.','Ein Wachposten der Verlassenen hielt mich an und fragte, ob ich einen Heiler brauche.','Ich sagte ja. Er schickte mich zum Apotheker. Schlimmste Untersuchung meines Lebens.',NULL,NULL,NULL,NULL),
(@STORIES_START+57,'deDE','Du hast WAS?!','Der Apotheker! Hahaha!','Du hast Glück, dass du noch lebst.','Das Dümmste und Mutigste, was ich je gehört habe.',NULL,NULL,NULL,NULL),
(@STORIES_START+58,'deDE','Ein Zwerg im Sumpfland brachte mir bei, den Regen zu lesen.','Leichter Regen heißt, die Krokilisken schlafen. Starker Regen heißt, sie haben Hunger.','Ich fragte, was kein Regen bedeutet.','Er sagte: "Im Sumpfland? Das ist noch nie passiert."',NULL,NULL,NULL,NULL),
(@STORIES_START+59,'deDE','Stimmt, da regnet es immer.','Hah! Noch nie passiert!','Eigentlich nützliches Wissen.','Meine Stiefel sind vom Sumpfland immer noch nass.',NULL,NULL,NULL,NULL),
(@STORIES_START+60,'deDE','Habt ihr vom kopflosen Reiter vom Hügel der Trauer gehört?','Einmal im Jahr reitet er und sucht nach seinem Kopf.','Ein Kind bot ihm einmal stattdessen einen Kürbis an.','Er nahm ihn. Und seitdem brennen jeden Herbst Kürbisse in Goldhain.',NULL,NULL,NULL,NULL),
(@STORIES_START+61,'deDE','Schlotternächte! Ich liebe es.','Ein Kürbiskopf, hahaha.','Sag seinen Namen nicht zu laut.','Mutiges Kind.',NULL,NULL,NULL,NULL),
(@STORIES_START+62,'deDE','Mein erstes Schwert bekam ich von einem Schmied in Seenhain.','Es war zu schwer, zu lang und leicht verbogen.','Er sagte: "Es kommt nicht auf das Schwert an, sondern auf den, der es hält."','Später erfuhr ich, dass er es nur loswerden wollte.','Aber die Worte blieben hängen. Und die Krümmung auch.',NULL,NULL,NULL),
(@STORIES_START+63,'deDE','Schlauer Schmied.','Trägst du es noch?','Hah! Die Krümmung blieb!','Gute Worte, auch wenn\'s ein Trick war.',NULL,NULL,NULL,NULL),
(@STORIES_START+64,'deDE','Shattrath bei Nacht ist etwas Besonderes.','Die Naaru summen, und die ganze Stadt leuchtet sanft.','Ich saß auf der Terrasse des Lichts und hörte einfach zu.','Ein Draeneikind setzte sich zu mir und sagte: "Sie singen für uns."',NULL,NULL,NULL,NULL),
(@STORIES_START+65,'deDE','Das ist schön.','Ich habe noch nie einen Naaru singen hören.','Kinder wissen so etwas.','Frieden mitten im Chaos.',NULL,NULL,NULL,NULL),
(@STORIES_START+66,'deDE','Ich habe einmal einen Monat lang die Burg Nethergarde bewacht.','Jede Nacht bewegte sich etwas draußen in den Verwüsteten Landen.','In der letzten Nacht kam es näher. Groß, rote Augen.','Es war ein verirrter Eber. Hat uns fast zu Tode erschreckt, das Schwein.',NULL,NULL,NULL,NULL),
(@STORIES_START+67,'deDE','Ein Eber! Hahaha!','Lieber ein Eber als ein Dämon.','Ich hätte zuerst geschossen.','Nethergarde macht jeden nervös.',NULL,NULL,NULL,NULL),
(@STORIES_START+68,'deDE','Meine Mutter sagte immer: Trau nie einem schlafenden Drachen.','Ich dachte, das sei nur eine Redewendung.','Dann fand ich einen, der in den Sümpfen des Elends schlief.','Ich schlich auf Zehenspitzen vorbei. Er öffnete ein Auge und sagte: "Gute Entscheidung."',NULL,NULL,NULL,NULL),
(@STORIES_START+69,'deDE','Er hat gesprochen?!','Hör auf deine Mutter.','Vielleicht ein grüner Drache. Die träumen.','Ich wäre umgekippt.',NULL,NULL,NULL,NULL),
(@STORIES_START+70,'deDE','Tausendwintersee. Habt ihr dort je gekämpft?','Belagerungsmaschinen, Feuer, Schnee, alles auf einmal.','Ich fuhr einen Verwüster direkt in eine Mauer. Die falsche Mauer.','Unsere eigene. Der Kommandant ließ sie mich mit bloßen Händen wieder aufbauen.',NULL,NULL,NULL,NULL),
(@STORIES_START+71,'deDE','Unsere eigene Mauer! Hahaha!','Das ist eine Geschichte für die Gilde.','Leichter Fehler im Schnee.','Hat der Kommandant dir je verziehen?',NULL,NULL,NULL,NULL),
(@STORIES_START+72,'deDE','In Süderstade gibt es ein kleines Mädchen, das jeden Reisenden zeichnet.','Sie zeichnete mich mit einer Krone und einem Drachen.','Ich sagte ihr, dass ich nur ein einfacher Abenteurer bin.','Sie sagte: "Noch nicht." Ich habe die Zeichnung immer noch.',NULL,NULL,NULL,NULL),
(@STORIES_START+73,'deDE','Eine zukünftige Seherin.','Eine Krone! Eure Majestät!','Pass gut auf die Zeichnung auf.','"Noch nicht." Das gefällt mir.',NULL,NULL,NULL,NULL),
(@STORIES_START+74,'deDE','Ich steckte mal in einem gnomischen Teleporter fest.','Für eine Sekunde war ich gleichzeitig in Gadgetzan und Ewige Warte.','Die eine Hälfte schwitzte, die andere fror.','Als ich rauskam, hatte ich eine andere Haarfarbe.',NULL,NULL,NULL,NULL),
(@STORIES_START+75,'deDE','Das erklärt einiges.','Gnome sollten keine Teleporter bauen.','Welche Farbe hatten sie vorher?','Hahaha, beides gleichzeitig!',NULL,NULL,NULL,NULL),
(@STORIES_START+76,'deDE','In Feralas bin ich auf einen der Riesenbäume geklettert.','Ich brauchte einen ganzen Tag bis zur Spitze.','Dort oben fand ich ein Nest mit einem schlafenden Hippogryph.','Ich kletterte sehr, sehr leise wieder runter. Das dauerte zwei Tage.',NULL,NULL,NULL,NULL),
(@STORIES_START+77,'deDE','Zwei Tage runter! Hahaha!','Mutig, oder dumm.','Die Bäume in Feralas sind gewaltig.','Ich hätte ihn aus Versehen geweckt.',NULL,NULL,NULL,NULL),
(@STORIES_START+78,'deDE','Einmal fand ich eine Flaschenpost am Strand von Tanaris.','Darauf stand: "Wenn du das findest, ich bin auf der Insel im Osten."','Ich ruderte hinaus. Die Insel war leer, bis auf eine Hütte.','Drin war noch eine Flasche: "Zu spät, ich habe ein Boot gefunden. Trotzdem danke!"',NULL,NULL,NULL,NULL),
(@STORIES_START+79,'deDE','Hahaha, trotzdem danke!','Wenigstens war er höflich.','Das ganze Rudern für nichts.','Ich liebe ein gutes Ende.',NULL,NULL,NULL,NULL),
(@STORIES_START+80,'deDE','Die Pestländer waren einmal das beste Ackerland von Lordaeron.','Mein Onkel baute bei Andorhal Weizen an.','Er ging an dem Tag, als das Korn schwarz wurde.','Er backt immer noch jeden Morgen Brot. Er sagt, so erinnert er sich.',NULL,NULL,NULL,NULL),
(@STORIES_START+81,'deDE','So viel ging verloren.','Dein Onkel ist ein starker Mann.','Die Geißel wird dafür bezahlen.','Das Brot würde ich gern probieren.',NULL,NULL,NULL,NULL),
(@STORIES_START+82,'deDE','Ich habe bei einem Mönch trainiert, der auf einem Finger balancieren konnte.','Ein Jahr lang versuchte ich, es ihm nachzumachen.','Ich brach mir drei Finger und einen Tisch.','Er sagte: "Gut. Jetzt kennst du deine Grenzen."',NULL,NULL,NULL,NULL),
(@STORIES_START+83,'deDE','Einen Tisch auch? Hahaha!','Harter Lehrer.','Weise Worte, schmerzhafte Lektion.','Zeig uns den Fingertrick!',NULL,NULL,NULL,NULL),
(@STORIES_START+84,'deDE','Hinter einem Wasserfall in Un\'Goro gibt es eine versteckte Höhle.','Drinnen leuchten die Wände mit Kristallen in allen Farben.','Ich saß stundenlang da. Dann lief draußen ein Teufelssaurier vorbei.','Danach saß ich noch sehr viel mehr Stunden da.',NULL,NULL,NULL,NULL),
(@STORIES_START+85,'deDE','Teufelssaurier! Ich würde mich auch verstecken.','Wo genau ist diese Höhle?','Hahaha, sehr viel mehr Stunden.','Un\'Goro ist voller Wunder.',NULL,NULL,NULL,NULL),
(@STORIES_START+86,'deDE','Ich werde nie vergessen, wie ich Sturmwind zum ersten Mal sah.','Die Tore, die Statuen, die Kanäle, alles weiß in der Sonne.','Ich stand so lange auf der Brücke, dass eine Wache fragte, ob ich mich verlaufen habe.','Ich sagte nein. Ich war endlich zu Hause.',NULL,NULL,NULL,NULL),
(@STORIES_START+87,'deDE','Sturmwind ist ein Anblick.','Das Gefühl kenne ich.','Zuhause ist, wo dein Herz ist.','Das ist ein schönes Ende.',NULL,NULL,NULL,NULL),
(@STORIES_START+88,'deDE','Ein Schamane in Orgrimmar hat mir einmal aus Knochen die Zukunft gelesen.','Er runzelte die Stirn, schüttelte sie erneut, runzelte sie noch mehr.','Ich fragte: "Ist es schlimm?" Er sagte: "Nein, das sind Hühnerknochen."','"Die wissen nur etwas über das Mittagessen."',NULL,NULL,NULL,NULL),
(@STORIES_START+89,'deDE','Hühnerknochen! Hahaha!','Und was war mit dem Mittagessen?','Die Geister haben Humor.','Typisch Orgrimmar.',NULL,NULL,NULL,NULL),
(@STORIES_START+90,'deDE','Ich war auf dem Schiff nach Nordend, als der Sturm kam.','Wellen höher als der Mast, alle haben gebetet.','Der Kapitän stand einfach da und rauchte seine Pfeife.','Danach fragte ich, warum er keine Angst hatte. Er sagte: "Hatte ich. Ich habe sie nur besser versteckt."',NULL,NULL,NULL,NULL),
(@STORIES_START+91,'deDE','Das ist Mut.','Ich hasse Schiffe.','Ein guter Kapitän.','Das merke ich mir.',NULL,NULL,NULL,NULL),
(@STORIES_START+92,'deDE','Mein Bruder wollte sich selbst Feuermagie beibringen.','Erster Versuch: Er hat sich die Augenbrauen angezündet.','Zweiter Versuch: die Vorhänge.','Beim dritten Versuch gelang ihm endlich ein Feuerball. Direkt in Mutters Suppe.','Heute ist er Erzmagier. Augenbrauen hat er immer noch keine.',NULL,NULL,NULL),
(@STORIES_START+93,'deDE','Keine Augenbrauen! Hahaha!','Deine arme Mutter.','Jeder Magier fängt irgendwo an.','Hat die Suppe überlebt?',NULL,NULL,NULL,NULL),
(@STORIES_START+94,'deDE','Ich habe einmal eine Nacht am Schrein des Gefallenen Kriegers verbracht.','Niemand sonst war da, nur ich und der Wind.','Um Mitternacht hörte ich Schritte, die langsam um den Schrein gingen.','Am Morgen hatte jemand frische Blumen hingelegt.',NULL,NULL,NULL,NULL),
(@STORIES_START+95,'deDE','Ein Geist, der Wache hält.','Das ist respektvoll, nicht gruselig.','Das Brachland birgt viele Erinnerungen.','Ich hab Gänsehaut.',NULL,NULL,NULL,NULL),
(@STORIES_START+96,'deDE','Ich habe in Dun Morogh einen Gnom vor einem Wolfsrudel gerettet.','Zum Dank schenkte er mir ein mechanisches Eichhörnchen.','Es folgte mir ein Jahr lang und redete in meinem Schlaf.','Eines Tages lief es mit einem echten Eichhörnchen davon. Ich hoffe, sie sind glücklich.',NULL,NULL,NULL,NULL),
(@STORIES_START+97,'deDE','Wahre Liebe! Hahaha!','Es hat in deinem Schlaf geredet?','Gnome machen die seltsamsten Geschenke.','Ich hoffe auch, dass sie glücklich sind.',NULL,NULL,NULL,NULL),
(@STORIES_START+98,'deDE','Ich erzähle euch vom besten Essen, das ich je hatte.','Es war nicht in einer Stadt oder einer Taverne. Es war genau hier.','Ein Feuer, etwas altes Brot und Freunde, die schlechten Geschichten zugehört haben.','Also danke. Jetzt erzählt mal jemand anderes, meine Kehle ist trocken.',NULL,NULL,NULL,NULL),
(@STORIES_START+99,'deDE','Auf die Freunde!','Deine Geschichten sind nicht schlecht.','Reich mal das Brot rüber.','Ach, wie schön.',NULL,NULL,NULL,NULL);
